var w = new WindowCounter(300);
w.Record(1); w.Record(1); w.Record(299); w.Record(300);
T.Eq("all four inside the window at 300", w.Count(300), 4L);
T.Eq("second 1 leaves at 301", w.Count(301), 2L);
w.Record(601);
T.Eq("a reused slot is reset", w.Count(601), 1L);
var e = new WindowCounter(300); e.Record(0);
T.Eq("exactly 300 s old is outside", e.Count(300), 0L);

var c = new WindowCounter(60);
Parallel.For(0, 8, t => { for (int i = 0; i < 10_000; i++) c.Record(1000); });
T.Eq("no lost increments", c.Count(1000), 80_000L);
var d = new WindowCounter(60); long last = 0; bool backwards = false;
var writers = Task.Run(() => Parallel.For(0, 4, t => { for (int i = 0; i < 20_000; i++) d.Record(2000); }));
while (!writers.IsCompleted) { long v = d.Count(2000); if (v < last) backwards = true; last = v; }
writers.Wait();
T.True("concurrent reads never go backwards", !backwards);
